import { createWorkspace, teardownWorkspace } from '@tigrisdata/agent-kit';
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import * as fs from 'fs';

async function main() {
  const trialIdRaw = fs.readFileSync('/logs/artifacts/trial_id', 'utf-8').trim();

  const normalize = (name: string) => name.toLowerCase().replace(/[^a-z0-9.-]/g, '-');

  const names = [
    normalize(`pool-agent-${trialIdRaw}-1`),
    normalize(`pool-agent-${trialIdRaw}-2`),
    normalize(`pool-agent-${trialIdRaw}-3`),
    normalize(`pool-agent-${trialIdRaw}-4`)
  ];

  const createPromises = names.map(name => 
    createWorkspace(name, { ttl: { days: 1 }, credentials: { role: "Editor" } })
  );

  const workspaceResponses = await Promise.all(createPromises);
  const workspaces = [];

  for (let i = 0; i < workspaceResponses.length; i++) {
    const res = workspaceResponses[i];
    if (res.error) {
      console.error(`Failed to create workspace ${names[i]}:`, res.error);
      process.exit(1);
    }
    if (res.data) {
      workspaces.push({ ...res.data, name: names[i] });
    }
  }

  const uploadPromises = workspaces.map(ws => {
    const s3 = new S3Client({
      endpoint: 'REDACTED',
      region: 'REDACTED',
      credentials: {
        accessKeyId: ws.credentials!.accessKeyId,
        secretAccessKey: ws.credentials!.secretAccessKey
      }
    });

    return s3.send(new PutObjectCommand({
      Bucket: ws.bucket,
      Key: 'init.txt',
      Body: ws.name
    }));
  });

  await Promise.all(uploadPromises);

  const summary = workspaces.map(ws => ({
    name: ws.name,
    bucket: ws.bucket
  }));

  fs.writeFileSync('/home/user/ws-pool/pool.json', JSON.stringify(summary, null, 2));

  const teardownPromises = workspaces.map(ws => teardownWorkspace(ws));
  await Promise.allSettled(teardownPromises);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

